[ENABLE]
aobscanmodule(INJECTcustomsrp,REResistance.exe,F3 44 0F 10 40 34 EB)
alloc(newmem,$36,INJECTcustomsrp)
label(code)
label(return)

newmem:
push rbx
mov rbx,[rsp+218]
mov rbx,[rbx+118]
cmp [rbx+14],2
jne code
mov ebx,64
cvtsi2ss xmm8,ebx
pop rbx
jmp return
code:
pop rbx
movss xmm8,[rax+34]
jmp return

INJECTcustomsrp:
jmp newmem
nop
return:
registersymbol(INJECTcustomsrp)

[DISABLE]
INJECTcustomsrp:
  db F3 44 0F 10 40 34

unregistersymbol(INJECTcustomsrp)
dealloc(newmem)
</AssemblerScript>
