newmem:
cmp dword ptr [rax+14],02
jne code2
mov dword ptr [rax+14],00
mov byte ptr [cpus],1
code2:
cmp dword ptr [rax+14],04
jne INJECTcusqm+10
jmp return

INJECTcusqm+06:
jmp newmem
nop
return:
registersymbol(INJECTcusqm)

newmem2:
mov eax,[rcx]
push r9
cmp byte ptr [cpus],1
jne code
mov r9,["REResistance.exe"+09DDBB70]
mov r9,[r9+98]
cmp r8,r9
jne code
pop r9
jmp return2
code:
pop r9
mov [r10+14],eax
jmp return2

INJECTdcty:
  jmp newmem2
  nop
return2:
registersymbol(INJECTdcty)

newmem3:
cmp byte ptr [cpus],1
jne code3
xorps xmm0,xmm0
mov byte ptr [cpus],0
code3:
cvtss2sd xmm1,xmm0
mov rcx,[rax+18]
jmp return3

INJECTnopecupu+05:
jmp newmem3
nop 3
return3:
registersymbol(INJECTnopecupu)

newmem4:
