        <CheatEntry>
          <ID>1337145691</ID>
          <Description>"Restart Game"</Description>
          <Options moHideChildren="1"/>
          <Color>1711FF</Color>
          <VariableType>Auto Assembler Script</VariableType>
          <AssemblerScript>{ Game   : REResistance.exe
  Version: 
  Date   : 2026-01-05
  Author : TBJ
}

[ENABLE]
aobscanmodule(INJECTrestart,REResistance.exe,80 B9 C2 03 00 00 00)
alloc(newmem,$2C,INJECTrestart)
alloc(restart,01,INJECTrestart)
registersymbol(restart)
label(code)
label(return)

restart:
db 00

newmem:
  cmp byte ptr [restart],01
  jne code
  mov byte ptr [restart],00
  cmp byte ptr [rcx+000003C2],01
  jmp return
code:
  cmp byte ptr [rcx+000003C2],00
  jmp return

INJECTrestart:
  jmp newmem
  nop 2
return:
registersymbol(INJECTrestart)

[DISABLE]
INJECTrestart:
  db 80 B9 C2 03 00 00 00

unregistersymbol(INJECTrestart)
unregistersymbol(restart)
dealloc(newmem)
dealloc(restart)
</AssemblerScript>
